import os
import base64

TARGET_DIR = os.path.join("tools", "tool_spec_auditor")

FILES_B64 = {
    "__init__.py": "IiIiClRvb2wgxJDhu5FpIHNvw6F0IENo4buJIHRpw6p1IEvhu7kgdGh14bqtdCAmIERhdGFzaGVldAoiIiIKZnJvbSAudmlldyBpbXBvcnQgcmVuZGVyX3NwZWNfYXVkaXRvcl90b29sCgpfX2FsbF9fID0gWyJyZW5kZXJfc3BlY19hdWRpdG9yX3Rvb2wiXQo=",
    
    "models.py": "",
    
    "parser_excel.py": "",
    
    "parser_pdf.py": "",
    
    "engine_rules.py": "",
    
    "engine_llm.py": "",
    
    "view.py": ""
}

def main():
    print(f"[*] Bắt đầu giải mã và tạo thư mục: {TARGET_DIR}")
    os.makedirs(TARGET_DIR, exist_ok=True)

    for filename, b64_content in FILES_B64.items():
        file_path = os.path.join(TARGET_DIR, filename)
        decoded_bytes = base64.b64decode(b64_content.encode("ascii"))
        with open(file_path, "wb") as f:
            f.write(decoded_bytes)
        print(f" -> Đã tạo thành công: {file_path}")

    print("\n✅ Toàn bộ module 'tools/tool_spec_auditor' đã được khởi tạo xong!")
    print("\nCác bước tiếp theo:")
    print("1. Mở file 'app.py' và import[cite: 1]:")
    print("   from tools.tool_spec_auditor.view import render_spec_auditor_tool")
    print("2. Đăng ký vào 'tools_registry'[cite: 1]:")
    print("   '🔬 Đối soát Chỉ tiêu Kỹ thuật & Datasheet': render_spec_auditor_tool,")
    print("3. Khởi chạy: streamlit run app.py")

if __name__ == "__main__":
    main()